SELECT count(*) FROM public.chartevents chartevents WHERE NOT EXISTS (SELECT 1 FROM public.admissions a, public.patients p, public.diagnoses_icd d, public.d_icd_diagnoses dd WHERE a.hadm_id = chartevents.hadm_id AND p.subject_id = a.subject_id AND p.anchor_age >= 50 AND d.hadm_id = a.hadm_id AND d.icd_code = 'N179' AND dd.icd_code = d.icd_code AND dd.icd_version = d.icd_version) AND NOT EXISTS (SELECT 1 FROM public.admissions a, public.drgcodes g WHERE a.hadm_id = chartevents.hadm_id AND g.hadm_id = a.hadm_id AND g.drg_type = 'APR' AND g.drg_severity >= 4);
